<template><q-page class="arena-page"><section class="hero"><p class="eyebrow">ARENA CONQUISTAAI</p><h1>Duelo de conhecimentos</h1><p>Crie, descubra ou entre em uma sala e confirme seus assuntos para iniciar.</p></section><q-banner v-if="error" rounded class="error">{{ error }}</q-banner><q-inner-loading :showing="loading"/><q-card v-if="!duel" flat bordered class="entry-card"><q-card-section><q-tabs v-model="mode" dense active-color="primary"><q-tab name="create" label="Criar"/><q-tab name="public" label="Salas públicas"/><q-tab name="private" label="Minhas privadas"/><q-tab name="join" label="Código privado"/></q-tabs><q-separator/><q-form v-if="mode===`create`" class="form" @submit.prevent="create"><q-select v-model="form.visibility" outlined label="Visibilidade" :options="[{label:`Pública`,value:`PUBLIC`},{label:`Privada`,value:`PRIVATE`}]" emit-value map-options/><q-select v-model="form.maxPlayers" outlined label="Participantes" :options="[2,3,4,5,6,7,8]"/><q-select v-model="form.questionCount" outlined label="Questões" :options="[5,10,15,20]"/><q-select v-model="form.questionSeconds" outlined label="Tempo" :options="[15,30,60]"/><q-btn type="submit" unelevated color="primary" no-caps :label="form.visibility===`PUBLIC`?`Criar sala pública`:`Criar sala privada`"/></q-form><q-list v-else-if="mode===`public`" separator><q-item v-for="room in publicRooms" :key="room.id"><q-item-section><q-item-label>{{ room.participantCount }}/{{ room.maxPlayers }} participantes</q-item-label><q-item-label caption>{{ room.questionCount }} questões · {{ room.questionSeconds }}s</q-item-label></q-item-section><q-item-section side><q-btn color="primary" no-caps label="Entrar" @click="joinPublic(room.id)"/></q-item-section></q-item><q-item v-if="!publicRooms.length"><q-item-section>Nenhuma sala pública aguardando.</q-item-section></q-item></q-list><q-list v-else-if="mode===`private`" separator><q-item v-for="room in privateRooms" :key="room.id" clickable @click="open(room.id)"><q-item-section><q-item-label>Sala privada</q-item-label><q-item-label caption>{{ room.participantCount }}/{{ room.maxPlayers }} participantes · {{ room.questionCount }} questões</q-item-label></q-item-section></q-item><q-item v-if="!privateRooms.length"><q-item-section>Você não criou salas privadas aguardando.</q-item-section></q-item></q-list><q-form v-else class="form one" @submit.prevent="join"><q-input v-model="code" outlined label="Código da sala" maxlength="8"/><q-btn type="submit" unelevated color="primary" no-caps label="Entrar no duelo"/></q-form></q-card-section></q-card><q-card v-else flat bordered class="duel-card"><q-card-section class="duel-head"><div><p class="eyebrow">SALA {{ duel.visibility===`PUBLIC`?`PÚBLICA`:`PRIVADA` }}</p><h2 v-if="duel.visibility===`PRIVATE`">{{ duel.code }}</h2></div><q-chip color="primary" text-color="white">{{ label }}</q-chip></q-card-section><q-separator/><q-card-section v-if="duel.status===`WAITING`"><h3>Escolha {{ duel.subjectsPerPlayer }} assunto(s)</h3><q-select v-model="selectedSubjects" outlined multiple emit-value map-options option-value="id" option-label="name" :options="subjects" :max-values="duel.subjectsPerPlayer" label="Assuntos"/><q-btn class="q-mt-md" color="primary" no-caps :disable="selectedSubjects.length!==duel.subjectsPerPlayer" label="Confirmar prontidão" @click="ready"/><q-list class="q-mt-md"><q-item v-for="player in duel.players" :key="player.userId"><q-item-section>{{ player.name }}</q-item-section><q-item-section side>{{ player.ready?`Pronto`:`Escolhendo` }}</q-item-section></q-item></q-list><q-btn v-if="duel.creatorUserId===userId && duel.players.every(p=>p.ready)" class="q-mt-md" color="primary" no-caps label="Iniciar duelo" @click="start"/></q-card-section><q-card-section v-else-if="duel.question"><div class="timer">{{ remaining }}s</div><h3>Questão {{ duel.currentPosition }} de {{ duel.questionCount }}</h3><p>{{ duel.question.statement }}</p><q-btn v-for="option in duel.question.options" :key="option.id" outline no-caps class="option" :disable="duel.answered" :label="option.label+`. `+option.content" @click="answer(option.id)"/></q-card-section><q-card-section v-else><q-spinner color="primary"/> Sincronizando…</q-card-section></q-card></q-page></template><script setup lang="ts">import {computed,onMounted,onBeforeUnmount,ref,watch} from "vue";import {useArena} from "./useArena";import {useArenaRealtime} from "./useArenaRealtime";const props=defineProps<{userId:string}>();const {duel,publicRooms,privateRooms,subjects,loading,error,loadLobby,create:createDuel,join:joinDuel,joinPublic:joinPublicDuel,ready:readyDuel,start:startDuel,answer:sendAnswer,refresh}=useArena();useArenaRealtime(refresh).connect();const mode=ref("create"),code=ref(""),selectedSubjects=ref<string[]>([]),form=ref({visibility:"PUBLIC" as "PUBLIC"|"PRIVATE",maxPlayers:2,subjectsPerPlayer:1,questionCount:5,questionSeconds:30}),now=ref(Date.now());const userId=props.userId;const label=computed(()=>duel.value?.status===`WAITING`?`Aguardando`:`Em andamento`);const remaining=computed(()=>duel.value?.deadlineAt?Math.max(0,Math.ceil((new Date(duel.value.deadlineAt).getTime()-now.value)/1000)):0);async function create(){await createDuel(form.value)}async function join(){await joinDuel(code.value.trim())}async function joinPublic(id:string){await joinPublicDuel(id)}async function open(id:string){await refresh(id)}async function ready(){await readyDuel(selectedSubjects.value)}async function start(){await startDuel()}async function answer(id:string){await sendAnswer(id)}watch(duel,d=>{if(d)history.replaceState(null,"",`?section=arena&duel=${d.id}`)});onMounted(async()=>{await loadLobby();const id=new URLSearchParams(location.search).get("duel");if(id)await refresh(id)});const interval=window.setInterval(()=>now.value=Date.now(),500);onBeforeUnmount(()=>clearInterval(interval));</script><style scoped>.arena-page{max-width:1060px;margin:auto;padding:42px 30px}.entry-card,.duel-card{max-width:760px;border-radius:22px}.form{display:grid;gap:14px;grid-template-columns:repeat(2,1fr);padding-top:20px}.form .q-btn{grid-column:1/-1}.one{grid-template-columns:1fr}.option{display:flex;width:100%;justify-content:flex-start;margin:8px 0}.error{margin-bottom:12px}.eyebrow{color:#5473a7;font-weight:800;letter-spacing:.1em}.timer{font-weight:800;color:#1565c0}@media(max-width:599px){.arena-page{padding:20px 16px}.form{grid-template-columns:1fr}}</style>
